function removeClass(n){const t=Swal.mixin({customClass:{confirmButton:"btn btn-success",cancelButton:"btn btn-danger me-2"},buttonsStyling:!1});t.fire({title:"Are you sure?",text:"You won't be able to revert this!",icon:"warning",showCancelButton:!0,confirmButtonText:"Yes, delete!",cancelButtonText:"No, cancel!",reverseButtons:!0}).then(i=>{i.isConfirmed?$.ajax({type:"DELETE",url:n,success:function(n){$.unblockUI();n.success?(swal.fire("Deleted!",n.message,"success"),datatablez.ajax.reload()):swal.fire("Deleted!",n.message,"error")},beforeSend:function(){blockcallback()},error:function(){$.unblockUI();Swal.fire({icon:"error",title:"Oops...",text:"Something went wrong!",footer:"Check internet connectivity"})},complete:function(){$.unblockUI()}}):i.dismiss===Swal.DismissReason.cancel&&t.fire("Cancelled","Class Record NOT Deleted","error")})}function blockcallback(){$.blockUI({message:'<div class="bs-spinner mt-4 mt-lg-0"><div class= "spinner-border text-success mr-2 mt-2" style="width: 10rem; height: 10rem;" role="status"><span class="sr-only">Loading...<\/span><\/div> ',fadeIn:800,overlayCSS:{backgroundColor:"#1b2024",opacity:.8,zIndex:1200,cursor:"wait"},css:{border:0,color:"#fff",zIndex:1201,padding:0,backgroundColor:"transparent"},onBlock:function(){}})}var font,clazz,datatablez;$(document).ready(function(){datatablez=$("#classtable").DataTable({processing:!0,serverSide:!0,filter:!0,paging:!0,responsive:!0,ajax:{url:"/Home/ClassData",type:"POST",datatype:"json"},columnDefs:[{targets:[0],visible:!0,searchable:!0}],columns:[{data:"id",render:function(n,t,i,r){return r.row+r.settings._iDisplayStart+1}},{data:"name",autoWidth:!0},{data:"elective",render:function(n){return n?`<span class="badge h4 bg-success">Elective Class</span>`:`<label class="badge h3 bg-warning">None Elective Class</label>`}},{data:null,render:function(n){return`
                        <div class="">
                            <button type="button" class="btn btn-primary btn-sm btn-edit-class" title="Edit Class Name" data-id="${n.id}" data-name="${n.name}" data-elective="${n.elective}" style="cursor:pointer">
                                <i class="bi bi-pencil-square"></i>
                            </button>
                            &nbsp;  &emsp;
                            <a onclick=removeClass("/api/classmanager/${n.id}") title="Permanently Remove class" class="btn btn-danger btn-sm" href="#" style="cursor:pointer">
                                <i class="bi bi-trash"></i>
                            </a>
                        </div>
                    `}}]});$(document).on("click",".btn-edit-class",function(){var i=$(this).data("id"),r=$(this).data("name"),n=String($(this).data("elective")).toLowerCase()==="true",t;$("#editClassModal input[name='_class.Name']").val(r);$("#editClassModal input[name='_class.Id']").val(i);$("#editClassModal input[name='customRadio'][value='Cando']").prop("checked",n);$("#editClassModal input[name='customRadio'][value='Cannot']").prop("checked",!n);t=new bootstrap.Modal(document.getElementById("editClassModal"));t.show()})});